    /**
     * Tests creating a new Approval.
     *
     * @return    Approval
     */
    public Approval testCreate() throws Throwable {
    Approval entity = null;

    LOGGER.info( "ApprovalTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Approval");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Approval" );

    try {
        entity = service.createApproval( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getApprovalId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Approval with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

