    /**
     * Tests getting all Approvals.
     *
     * @return    Collection
     */
    public List<Approval> testGetAll() throws Throwable {
    LOGGER.info( "ApprovalTest:testGetAll() - Retrieving Collection of Approvals:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Approval : " );
    List<Approval> collection  = null;

    try {
        // call the static get method on the ApprovalService
        collection = service.getAllApproval();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Approval currEntity  = null;
            Iterator<Approval> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getApprovalId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

